urlset:
{%- for sitemap_entry in entries %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endfor %}
{#- Zola's own sitemap, plus pages on the same domain that Zola does not
    build, such as other GitHub Pages sites served under it (in
    config.toml: [extra] sitemap_extra = ["https://...", ...]) #}
{%- for loc in config.extra.sitemap_extra | default(value=[]) %}

    {{ loc | escape_xml | safe }}

{%- endfor %}
